def right_side_view(root):
    if root is None:
        return []
    result = []
    queue = [root]
    while queue:
        level_size = len(queue)
        next_queue = []
        for i in range(level_size):
            node = queue[i]
            if i == level_size - 1:
                result.append(node.val)                      # record only the LAST node of this round
            if node.left:
                next_queue.append(node.left)
            if node.right:
                next_queue.append(node.right)
        queue = next_queue
    return result

